const rows = $input
  .all()
  .map(item => item.json || {});

let batch = {};

try {
  batch =
    $('Postgres — захватить готовый batch').first().json || {};
} catch {}

function objectValue(value, fallback) {
  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value)
  ) {
    return value;
  }

  if (typeof value === 'string' && value.trim()) {
    try {
      const parsed = JSON.parse(value);

      if (
        parsed &&
        typeof parsed === 'object' &&
        !Array.isArray(parsed)
      ) {
        return parsed;
      }
    } catch {}
  }

  return fallback;
}

const records = rows.map(row => {
  const reportFields =
    objectValue(row.reportFields, {});

  let resultJson =
    objectValue(row.resultJson, null);

  if (
    String(row.processingStatus || '').toLowerCase() !== 'completed'
  ) {
    resultJson = {
      reportId:
        Number(row.reportId) || null,

      seldonId:
        row.seldonId || null,

      reportFields,

      fields: {
        tenderStatus:
          'Ошибка обработки',

        tenderStatusReason:
          'Ошибка workflow',

        tenderStatusNote:
          String(
            row.errorMessage ||
            'Tender worker завершился с ошибкой.'
          )
      },

      warnings: [
        String(
          row.errorMessage ||
          'Tender worker завершился с ошибкой.'
        )
      ]
    };
  }

  return {
    ...row,

    reportFields,

    resultJson,

    recordKey:
      row.recordKey ||
      row.cacheKey
  };
});

let sourceFiles =
  batch.sourceFiles;

if (typeof sourceFiles === 'string') {
  try {
    sourceFiles = JSON.parse(sourceFiles);
  } catch {
    sourceFiles = [];
  }
}

if (!Array.isArray(sourceFiles)) {
  sourceFiles = [];
}

return [
  {
    json: {
      status:
        'ready_for_csv',

      batchId:
        batch.batchId || null,

      batchDate:
        batch.batchDate || null,

      createdAt:
        batch.createdAt || null,

      finalizedAt:
        new Date().toISOString(),

      expectedCount:
        Number(batch.expectedCount || records.length),

      completedCount:
        Number(batch.completedCount || 0),

      failedCount:
        Number(batch.failedCount || 0),

      sourceFiles,
      records
    }
  }
];

const summary = $input.first().json || {};
const records = Array.isArray(summary.records) ? summary.records : [];

function parseJson(value) {
  if (!value) return {};
  if (typeof value === 'object') return value;

  try {
    return JSON.parse(String(value));
  } catch {
    return {};
  }
}

function unwrap(value) {
  if (
    value &&
    typeof value === 'object' &&
    !Array.isArray(value) &&
    Object.prototype.hasOwnProperty.call(value, 'value')
  ) {
    return value.value;
  }

  return value;
}

function field(result, name) {
  return unwrap(result?.fields?.[name]);
}

function firstDefined(...values) {
  for (const value of values) {
    const unwrapped = unwrap(value);

    if (
      unwrapped !== undefined &&
      unwrapped !== null &&
      String(unwrapped).trim() !== ''
    ) {
      return unwrapped;
    }
  }

  return '';
}

function cell(value) {
  const unwrapped = unwrap(value);

  if (unwrapped === undefined || unwrapped === null) return '';

  if (Array.isArray(unwrapped)) {
    return unwrapped
      .map((item) =>
        typeof item === 'object' ? JSON.stringify(item) : String(item)
      )
      .join(', ');
  }

  if (typeof unwrapped === 'object') {
    return JSON.stringify(unwrapped);
  }

  return String(unwrapped);
}

function escapeCsv(value) {
  const text = cell(value);

  if (/[;"\r\n]/.test(text)) {
    return `"${text.replace(/"/g, '""')}"`;
  }

  return text;
}

function decision(result) {
  const value =
    result?.decision ||
    result?.decisionResult ||
    result?.debug?.tenderDecision ||
    {};

  return value && typeof value === 'object' ? value : {};
}

