    timeZone: 'Europe/Moscow',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(new Date());

function reportFields(entry) {
  // Главный резервный источник — input_json задания.
  // Dispatcher сохраняет туда исходную строку CSV целиком.
  const inputJson = parseJson(entry.record?.inputJson);

  const candidates = [
    inputJson?.reportFields,
    inputJson,
    entry.record?.reportFields,
    entry.result?.sourceTender?.reportFields,
    entry.result?.sourceReportFields,
    entry.result?.reportFields,
  ];

  const merged = {};

  for (const candidate of candidates) {
    if (
      candidate &&
      typeof candidate === 'object' &&
      !Array.isArray(candidate)
    ) {
      Object.assign(merged, candidate);
    }
  }

  return merged;
}

function sourceValue(entry, column) {
  const source = reportFields(entry);
  const key = column.key;

  if (key === 'ID') {
    return firstDefined(
      source.ID,
      source.SeldonID,
      entry.result?.seldonId,
      entry.record?.seldonId
    );
  }

  if (key === 'Код ТО') {
    return firstDefined(
      source[key],
      entry.result?.toCode,
      field(entry.result, 'toCode'),
      entry.record?.toCode
    );
  }

  if (key === 'Код ФЗ') {
    return firstDefined(
      source[key],
      entry.result?.lawCode,
      entry.record?.lawCode
    );
  }

  return firstDefined(source[key]);
}

const availableReportIds = [...new Set(
  prepared
    .map((entry) => Number(
      entry.result?.reportId ??
      entry.record?.reportId
    ))
    .filter((reportId) => [1, 2, 3].includes(reportId))
)].sort((a, b) => a - b);

if (!availableReportIds.length) {
  throw new Error('Не найдено результатов для формирования CSV 223, gos или kom.');
}

return availableReportIds.map((reportId) => {
  const config = REPORTS[reportId];

  const reportRecords = prepared.filter((entry) =>
    Number(
      entry.result?.reportId ??
      entry.record?.reportId
    ) === reportId
  );

  const headers = [
    ...config.columns.map((column) => column.header),
    ...AUTOFILL_COLUMNS.map(([title]) => title),
  ];

  const lines = [
    headers.map(escapeCsv).join(';'),
    ...reportRecords.map((entry) => {
      const sourceCells = config.columns.map((column) =>
        escapeCsv(sourceValue(entry, column))
      );

      const autofillCells = AUTOFILL_COLUMNS.map(([, resolver]) =>
        escapeCsv(resolver(entry))
      );

      return [...sourceCells, ...autofillCells].join(';');
    }),
  ];

  return {
    json: {
      status: summary.status,
      batchId: summary.batchId,
      batchDate,
      finishedAt: summary.finishedAt,
      reportId,
      reportName: config.title,
      processedCount: summary.processedCount,
      invalidCount: summary.invalidCount,
      totalHandled: summary.totalHandled,
      csvRowCount: reportRecords.length,
      csvColumnCount: headers.length,
      csvText: '\uFEFF' + lines.join('\r\n'),
      fileName: `daily_autofill_${config.slug}_${batchDate}.csv`,
    },
  };
});

const items = $input.all();

let batch = {};

try {
  batch =
    $('Собрать Daily Batch Summary из PostgreSQL').first().json || {};
} catch {}

const binary = {};
const files = [];

for (const item of items) {
  const slug =
    String(
      item.json?.reportName ||
      item.json?.reportSlug ||
      item.json?.slug ||
      'report'
    )
      .toLowerCase()
      .replace(/[^a-z0-9а-я_-]+/gi, '_');

  const sourceBinary =
    item.binary?.data;

  if (!sourceBinary) {
    continue;
  }

  const binaryKey =
    `file_${slug}`;

  binary[binaryKey] =
    sourceBinary;

  files.push({
    binaryKey,
    fileName:
      sourceBinary.fileName ||
      item.json?.fileName ||
      `${slug}.csv`
  });
}

if (!files.length) {
  throw new Error(
    'Finalizer не сформировал ни одного CSV-файла.'
  );
}

return [
  {
    json: {
      batchId:
        batch.batchId || null,

      batchDate:
        batch.batchDate || null,

      expectedCount:
        Number(batch.expectedCount || 0),

      completedCount:
        Number(batch.completedCount || 0),

      failedCount:
        Number(batch.failedCount || 0),

      files,

      attachmentFields:
        files
          .map(file => file.binaryKey)
          .join(','),

      emailSubject:
        `Daily autofill ${batch.batchDate || ''} — batch ${batch.batchId || ''}`,

      emailText:
        [
          `Обработка batch ${batch.batchId || ''} завершена.`,
          `Всего заданий: ${Number(batch.expectedCount || 0)}.`,
          `Успешно: ${Number(batch.completedCount || 0)}.`,
          `С ошибкой: ${Number(batch.failedCount || 0)}.`,
          `Файлов: ${files.length}.`
        ].join('\n')
    },

    binary
  }
];

const finished =
  $input.first().json || {};

let filesItem = {
  json: {},
  binary: {}
};

try {
  filesItem =
    $('Собрать вложения').first() || filesItem;
} catch {}

return [
  {
    json: {
      ...(filesItem.json || {}),
      ...finished,
      status:
        'finished'
    },

    binary:
      filesItem.binary || {}
  }
];

return $input.all().map(item => {
  const row = item.json || {};

  let payload = row.payload;

  if (typeof payload === 'string') {
    try {
      payload = JSON.parse(payload);
    } catch {
      payload = {};
    }
  }

  if (
    !payload ||
    typeof payload !== 'object' ||
    Array.isArray(payload)
  ) {
    payload = {};
  }

  return {
    json: {
      ...payload,

      jobRecordKey:
        row.jobRecordKey,

      batchId:
        row.batchId ||
        payload.batchId ||
        null,

      asyncDispatch:
        true,

      maxTenderActive:
        Number(row.maxTenderActive || 5),

      controllerDispatchAt:
        new Date().toISOString()
    }
  };
});

